constraints:
1 ≤ N ≤ 10^{4}

expected time complexity: O(N)
expected auxiliary space: O(1)

standard_solution_code:
class Solution:

	def countFriendsPairings(self, n):
		if n <= 2:
			return n
		dp = [0 for i in range(n)]
		dp[0] = 1
		dp[1] = 2
		for i in range(2, n):
			dp[i] = (dp[i - 1] + i * dp[i - 2]) % (10 ** 9 + 7)
		return dp[n - 1]
